import sys
from functools import lru_cache

data = sys.stdin.read().split()
n, fee = int(data[0]), int(data[1])
prices = [int(x) for x in data[2:2 + n]]

@lru_cache(maxsize=None)
def go(i, holding):
    if i == n:
        return 0
    best = go(i + 1, holding)
    if holding:
        best = max(best, prices[i] - fee + go(i + 1, False))
    else:
        best = max(best, -prices[i] + go(i + 1, True))
    return best

print(go(0, False))

