def gen(rng):
    def fmt(prices, fee):
        return f'{len(prices)} {fee}\n' + ' '.join(map(str, prices))
    tests = [fmt([5], 0), fmt([5], 3), fmt([1, 4, 2, 6, 3, 8], 2), fmt([9, 7, 5, 3, 1], 1), fmt([1, 3, 2, 8, 4, 9], 2),
             fmt([2, 2, 2, 2], 0), fmt([1, 5], 10), fmt([1, 5], 3), fmt([1, 100, 1, 100, 1, 100], 0)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(2):
            hi = rng.choice([5, 20, 100])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)], rng.randint(0, hi // 2 + 1)))
    N = 100000
    tests.append(fmt([rng.randint(1, 50000) for _ in range(N)], rng.randint(0, 50000)))
    tests.append(fmt([rng.randint(1, 50000) for _ in range(N)], 1))
    tests.append(fmt([50000 if i % 2 else 1 for i in range(N)], 0))
    tests.append(fmt([50000 if i % 2 else 1 for i in range(N)], 50000))
    tests.append(fmt([i // 2 + 1 for i in range(N)], 5))
    return tests

